    39	  const row = getDb()
    40	    .insert(subscriptions)
    41	    .values({
    42	      id: newId(),
    43	      orgId,
    44	      plan,
    45	      interval,
    46	      status: plan === "free" ? "active" : "trialing",
    47	      seats: 1,
    48	      currentPeriodStart: stamp,
    49	      currentPeriodEnd: periodEnd,
    50	      cancelAt: null,
    51	      createdAt: stamp,
    52	      updatedAt: stamp,
    53	    })
    54	    .returning()
    55	    .get();
    56	
    57	  return toSubscription(row);
    58	}
