          },
        };
      }

      return requestPasswordResetAction(parsed.data);
    },
    null,
  );

  if (state?.ok === true) {
    return (
      <div className="space-y-3">
        <h1 className="text-lg font-semibold">Check your inbox</h1>
        <p className="text-sm text-slate-600">
