/* TEMPORARY probe — delete before finishing. */
import { beforeAll, beforeEach, describe, expect, it } from "vitest";
import { toAppError } from "@/lib/errors";
import { resetRateLimits } from "@/lib/rate-limit";
import * as userRepo from "@/server/repositories/user-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { register } from "@/server/services/auth-service";
import { resetTestDb, setupTestDb } from "./helpers/db";

const PW = "Correct-Horse-9battery";
let n = 0;
function input(name: string, email?: string) {
  n += 1;
  return {
    name,
    email: email ?? `user${n}@example.com`,
    password: PW,
    confirmPassword: PW,
    acceptTerms: true as const,
  };
}

const report: Record<string, unknown> = {};

beforeAll(async () => {
  await setupTestDb();
});
beforeEach(async () => {
  await resetTestDb();
  resetRateLimits();
});

async function attempt(label: string, fn: () => Promise<unknown>) {
  try {
    const r = (await fn()) as { org?: { name: string; slug: string } };
    report[label] = r.org ? { ok: true, org: r.org.name, slug: r.org.slug } : { ok: true };
  } catch (e) {
    const shape = toAppError(e);
    report[label] = { ok: false, code: shape.code, msg: shape.message, raw: (e as Error).name };
  }
}

describe("probe", () => {
  it("names", async () => {
    for (const name of ["Admin", "Billing", "Support", "Taskflow", "Al", "J", "山田", "Alice"]) {
      await attempt(`name:${name}`, () => register(input(name)));
    }
    await attempt("name:80chars", () => register(input("A".repeat(80))));
    await attempt("name:80chars-with-hyphen-collision-1", () => register(input("lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor")));
    await attempt("name:80chars-with-hyphen-collision-2", () => register(input("lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor")));
    console.log("NAMES\n" + JSON.stringify(report, null, 2));
    expect(true).toBe(true);
  });

  it("email + duplicate + rate", async () => {
    report.__reset = "x";
    await attempt("email:mixed-case", () => register(input("Alice", "Alice@Example.com")));
    const found = await userRepo.findUserByEmail("alice@example.com");
    report["lookup-lowercase-finds-mixed"] = found?.email ?? null;
    await attempt("dup:same-lower", () => register(input("Alice Two", "alice@example.com")));
    await attempt("dup:same-mixed", () => register(input("Alice Three", "ALICE@example.com")));
    const orgs = await orgRepo.listTakenOrgSlugs("alice");
    report["alice-orgs"] = orgs;
    let denied = 0;
    for (let i = 0; i < 60; i += 1) {
      try {
        await register(input(`Burst ${i}`));
      } catch (e) {
        denied += 1;
        if (denied === 1) report["burst-first-error"] = { code: toAppError(e).code, msg: toAppError(e).message };
      }
    }
    report["burst-denied-of-60"] = denied;
    console.log("EMAIL\n" + JSON.stringify(report, null, 2));
    expect(true).toBe(true);
  });
});

