/** Base for a slug derived from a name that leaves nothing usable behind. */
export const WORKSPACE_SLUG_FALLBACK = "workspace";

/**
 * Derives a slug from `input` that collides with nothing in `taken`, by
 * appending `-2`, `-3`, … Repositories pass their existing slug set in.
 */
export function uniqueSlug(input: string, taken: Iterable<string>): string {
  const base = slugify(input) || "item";
  const used = new Set(taken);
  if (!used.has(base) && !isReservedSlug(base)) return base;

  // Trimming the stem keeps the suffix from landing after a hyphen: `a-` + `-2`.
  const stem = base.slice(0, SLUG_MAX_LENGTH - 5).replace(/-+$/, "");
  for (let suffix = 2; suffix < 1_000; suffix += 1) {
    const candidate = `${stem}-${suffix}`;
    if (!used.has(candidate) && !isReservedSlug(candidate)) return candidate;
  }
  throw new InvalidSlugError(base, "exhausted unique suffixes");
}

/**
 * Where a slug derived from a person's name starts. It never refuses: a result
 * shorter than the minimum length is replaced by `workspace`. Reserved words are
 * kept, and `uniqueSlug()` suffixes them, so `Admin` becomes `admin-2`.
 */
export function derivedSlugBase(input: string): string {
  const slug = slugify(input);
  return slug.length >= SLUG_MIN_LENGTH ? slug : WORKSPACE_SLUG_FALLBACK;
}

