/**
 * A token bucket refused the attempt. Thrown by services that guard an
 * unauthenticated endpoint; the caller is told to wait, never that it failed.
 */
export class RateLimitedError extends Error {
  readonly code = "rate_limited" as const;

  constructor(
    readonly bucketKey: string,
    readonly resetAt: IsoTimestamp,
  ) {
    super(`Rate limit exceeded for ${bucketKey}; retry after ${resetAt}`);
    this.name = "RateLimitedError";
  }
}

/** Sign-up for an address that already has an account. Nothing is created. */
export class DuplicateAccountError extends Error {
  readonly code = "conflict" as const;

  constructor() {
    super("An account with that email already exists. Sign in instead.");
    this.name = "DuplicateAccountError";
  }
}

