export async function register(
  input: RegisterInput,
): Promise<{ user: User; org: Organization }> {
  const verdict = await consumeRateLimit(ANONYMOUS_ORG, REGISTER_BUCKET);
  if (!verdict.allowed) {
    throw new RateLimitedError(REGISTER_BUCKET, verdict.resetAt);
  }

  if (await userRepo.findUserByEmail(input.email)) {
    throw new DuplicateAccountError();
  }

  const slugBase = derivedSlugBase(input.name);
  const slug = uniqueSlug(slugBase, await orgRepo.listTakenOrgSlugs(slugBase));

  const passwordHash = await hashPassword(input.password);
  let user: User;
  try {
    user = await userRepo.insertUser({
      email: input.email,
      name: input.name,
      passwordHash,
    });
  } catch (error) {
    // A concurrent sign-up for the same address can pass the lookup above and
    // lose at the unique index; that is the same refusal.
    if (isUniqueViolation(error)) throw new DuplicateAccountError();
    throw error;
  }

  const org = await createOrganization(user.id, {
    name: workspaceNameFor(input.name),
    slug,
    plan: "free",
  });

  const welcome = await renderEmail("welcome", {
    userName: user.name,
    orgName: org.name,
    dashboardUrl: `${env.appUrl}${orgPath(org.slug)}`,
  });
  await sendEmail({ to: user.email, ...welcome });

  return { user, org };
}

/**
 * `<name>'s workspace`, with the name shortened until the whole fits the limit
 * the workspace forms enforce. Counted in code points, as the schema counts.
 */
function workspaceNameFor(name: string): string {
  const room = ORGANIZATION_NAME_MAX - [...WORKSPACE_SUFFIX].length;
  const display = [...name.trim()].slice(0, room).join("").trimEnd();
  return `${display}${WORKSPACE_SUFFIX}`;
}

/** SQLite's code for a unique index hit; `users` has one, on the address. */
function isUniqueViolation(error: unknown): boolean {
  return (
    typeof error === "object" &&
    error !== null &&
    "code" in error &&
    error.code === "SQLITE_CONSTRAINT_UNIQUE"
  );
}

